/**
 * @method
 * @name nado#createOrderWs
 * @description create a trade order over the v2 gateway WebSocket
 * @see https://docs.nado.xyz/developer-resources/api/gateway/websocket-v2
 * @see https://docs.nado.xyz/developer-resources/api/gateway/executes/place-order
 * @param {string} symbol unified symbol of the market to create an order in
 * @param {string} type must be 'limit'
 * @param {string} side 'buy' or 'sell'
 * @param {float} amount how much of currency you want to trade in units of base currency
 * @param {float} [price] the price at which the order is to be fulfilled, in units of the quote currency
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @param {string} [params.subaccount] the 12-byte subaccount identifier, defaults to 'default'
 * @param {string|int} [params.expiration] order expiration timestamp in seconds, defaults to 4294967295
 * @param {string|int} [params.appendix] pre-encoded order appendix
 * @param {boolean} [params.reduceOnly] true if the order should only reduce position
 * @param {boolean} [params.postOnly] true to create a post-only order
 * @param {string} [params.timeInForce] 'GTC', 'IOC', 'FOK', or 'PO'
 * @param {boolean} [params.spotLeverage] whether leverage should be used for spot, defaults to true, exchange-specific alias params.spot_leverage
 * @param {int} [params.id] client-provided request id used to correlate the out-of-order v2 response, autogenerated when omitted
 * @returns {object} an [order structure]{@link https://docs.ccxt.com/#/?id=order-structure}
 */
func (this *Nado) CreateOrderWsAsync(symbol string, typeVar string, side string, amount any, optionalArgs ...any) <-chan ccxt.AsyncResult[ccxt.Order] {
	ch := make(chan ccxt.AsyncResult[ccxt.Order], 1)
	go this.createOrderWsBody(ch, symbol, typeVar, side, amount, optionalArgs...)
	return ch
}
func (this *Nado) createOrderWsBody(ch chan ccxt.AsyncResult[ccxt.Order], symbol string, typeVar string, side string, amount any, optionalArgs ...any) any {
	defer close(ch)
	defer ccxt.ReturnPanicError(ch)
	var price *float64 = ccxt.GetArgFloat64Ptr(optionalArgs, 0, nil)
	_ = price
	var params map[string]any = ccxt.GetArgMap(optionalArgs, 1, map[string]any{})
	_ = params
	this.CheckRequiredCredentials()

	r := <-this.LoadMarketsAsync()
	if r.Err != nil {
		panic(r.Err)
	}
	var market map[string]any = this.Market(symbol)
	var paramsExtended map[string]any = this.Extend(map[string]any{
		"id": this.RequestId(),
	}, params)
	var requestIdString *string = this.SafeString(paramsExtended, "id")
	if requestIdString == nil {
		panic(ccxt.ArgumentsRequired(this.Id + " ws execute requires params.id"))
	}

	r1 := <-this.CreateOrderRequestAsync(symbol, typeVar, side, amount, price, paramsExtended)
	if r1.Err != nil {
		panic(r1.Err)
	}
	var request any = nil
	if r1.Value != nil {
		request = r1.Value
	}
	var placeOrder map[string]any = this.SafeDictMap(request, "place_order", map[string]any{})
	if ccxt.InOp(placeOrder, "trigger") {
		panic(ccxt.NotSupported(this.Id + " createOrderWs() does not support trigger orders, use createOrder() instead"))
	}

	r2 := <-this.WatchExecuteRequestAsync(*requestIdString, request)
	if r2.Err != nil {
		panic(r2.Err)
	}
	var response any = nil
	if r2.Value != nil {
		response = r2.Value
	}

	//
	//     {
	//         "status": "success",
	//         "signature": "0x...",
	//         "data": {
	//             "digest": "0x..."
	//         },
	//         "request_type": "execute_place_order",
	//         "id": 100
	//     }
	//
	ch <- ccxt.AsyncResult[ccxt.Order]{Value: this.ParseOrder(this.Extend(map[string]any{
		"place_order": placeOrder,
	}, response), market)}
	return nil
}

