func (this *Nado) authenticateBody(ch chan ccxt.AsyncResult[*string], optionalArgs ...any) any {
	defer close(ch)
	defer ccxt.ReturnPanicError(ch)
	var params map[string]any = ccxt.GetArgMap(optionalArgs, 0, map[string]any{})
	_ = params
	this.CheckRequiredCredentials()
	var url *string = this.SafeString(this.UrlsApi["ws"], "subscriptions")
	var client ccxt.ClientInterface = this.Client(url)
	var messageHash string = "authenticated"
	var authenticated any = client.(ccxt.ClientInterface).SubscriptionSafe(messageHash)
	if authenticated != nil {
		var future any = client.(ccxt.ClientInterface).FutureGet(messageHash)
		if future != nil {

			r := <-future.(*ccxt.Future).Await()
			if r.Err != nil {
				panic(r.Err)
			}
			var resolved *string
			switch resolvedBox := r.Value.(type) {
			case *string:
				resolved = resolvedBox
			case string:
				resolved = &resolvedBox
			default:
				_ = resolvedBox
			}
			ch <- ccxt.AsyncResult[*string]{Value: resolved}
			return nil
		}

		var resolved1 *string
		switch resolved1Box := authenticated.(type) {
		case *string:
			resolved1 = resolved1Box
		case string:
			resolved1 = &resolved1Box
		default:
			_ = resolved1Box
		}
		ch <- ccxt.AsyncResult[*string]{Value: resolved1}
		return nil
	}
	recvWindow, paramsRecvWindow := this.HandleOptionIntegerAndParams(params, "authenticate", "recvWindow", 5000)
	subaccount, paramsSubaccount := this.HandleOptionStringAndParams(paramsRecvWindow, "authenticate", "subaccount", "default")
	var id int64 = this.RequestId()
	var sender any = this.CreateSubaccount(this.WalletAddress, subaccount)
	var expiration any = this.Sum(this.Milliseconds(), recvWindow)
	var tx map[string]any = map[string]any{
		"sender":     sender,
		"expiration": this.NumberToString(expiration),
	}

	r1 := <-this.QueryContractsAsync()
	if r1.Err != nil {
		panic(r1.Err)
	}
	var contracts map[string]any = r1.Value
	var chainId *string = this.SafeString(contracts, "chain_id")
	var endpointAddress *string = this.SafeString(contracts, "endpoint_addr")
	if endpointAddress == nil {
		panic(ccxt.ExchangeError(this.Id + " authenticate() requires endpoint_addr from contracts query"))
	}
	var signature any = this.SignStreamAuthentication(tx, chainId, *endpointAddress)
	var request map[string]any = map[string]any{
		"method":    "authenticate",
		"id":        id,
		"tx":        tx,
		"signature": signature,
	}
	client.(ccxt.ClientInterface).SubscriptionSet("authentication:"+*this.SafeString(request, "id", ""), messageHash)

	r2 := <-this.Watch(url, messageHash, this.Extend(request, paramsSubaccount), messageHash)
	if r2.Err != nil {
		panic(r2.Err)
	}
	var resolved2 *string
	switch resolved2Box := r2.Value.(type) {
	case *string:
		resolved2 = resolved2Box
	case string:
		resolved2 = &resolved2Box
	default:
		_ = resolved2Box
	}
	ch <- ccxt.AsyncResult[*string]{Value: resolved2}
	return nil
}
func (this *Nado) SignStreamAuthentication(tx map[string]any, chainId *string, endpointAddress string) any {
	var domain map[string]any = map[string]any{
		"name":              "Nado",
		"version":           "0.0.1",
		"chainId":           chainId,
		"verifyingContract": endpointAddress,
	}
	var messageTypes map[string]any = map[string]any{
		"StreamAuthentication": []any{map[string]any{
			"name": "sender",
			"type": "bytes32",
		}, map[string]any{
			"name": "expiration",
			"type": "uint64",
		}},
	}
	var encoded []uint8 = this.EthEncodeStructuredData(domain, messageTypes, tx)
	return this.SignHash(this.Hash(encoded, ccxt.Keccak, "hex"), this.PrivateKey)
}
func (this *Nado) CreatePublicSubscriptionRequest(method string, streamType any, optionalArgs ...any) map[string]any {
	var market map[string]any = ccxt.GetArgMap(optionalArgs, 0, nil)
	_ = market
	id := ccxt.GetArg(optionalArgs, 1, nil)
	_ = id
	var params map[string]any = ccxt.GetArgMap(optionalArgs, 2, map[string]any{})
	_ = params
	var stream map[string]any = map[string]any{
		"type": streamType,
	}
	if market != nil {
		stream["product_id"] = this.ParseToInt(this.SafeString(market, "id"))
	}
	return map[string]any{
		"method": method,
		"stream": this.DeepExtend(stream, params),
		"id":     id,
	}
}
